import{r as i}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as c,o as a,c as g,b6 as o,J as r,k as l}from"./chunks/framework.BUXTSoD9.js";const m=JSON.parse('{"title":"Từ ý tưởng đến sản phẩm AI - Lộ trình học tập Easy-Vibe","description":"Lộ trình học tập lập trình AI hoàn chỉnh: từ người mới bắt đầu đến phát triển full-stack. Làm chủ Vibe Coding, Claude Code, Cursor và các công cụ AI IDE, học tư duy sản phẩm, phát triển full-stack và tích hợp năng lực AI.","frontmatter":{"title":"Từ ý tưởng đến sản phẩm AI - Lộ trình học tập Easy-Vibe","description":"Lộ trình học tập lập trình AI hoàn chỉnh: từ người mới bắt đầu đến phát triển full-stack. Làm chủ Vibe Coding, Claude Code, Cursor và các công cụ AI IDE, học tư duy sản phẩm, phát triển full-stack và tích hợp năng lực AI."},"headers":[],"relativePath":"vi-vn/stage-1/learning-map/index.md","filePath":"vi-vn/stage-1/learning-map/index.md"}'),p={name:"vi-vn/stage-1/learning-map/index.md"},b=Object.assign(p,{setup(u){const t=i["vi-vn/stage-1/learning-map"]??[];return(s,n)=>{const h=c("RelatedArticlesSection");return a(),g("div",null,[n[0]||(n[0]=o('<h1 id="tu-y-tuong-đen-san-pham-ai" tabindex="-1">Từ ý tưởng đến sản phẩm AI <a class="header-anchor" href="#tu-y-tuong-đen-san-pham-ai" aria-label="Permalink to “Từ ý tưởng đến sản phẩm AI”">​</a></h1><div class="info custom-block"><p class="custom-block-title">Lời cảm ơn đặc biệt</p><p>Đặc biệt cảm ơn các bạn sinh viên đến từ <strong>Viện Nghiên cứu Sinh viên Quốc tế Đại học Thanh Hoa, Thâm Quyến</strong> đã thử nghiệm, phản hồi và ủng hộ khóa học này! Những ý kiến và đóng góp của các bạn đã giúp khóa học trở nên tốt hơn. <a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 Xem danh sách người đóng góp đầy đủ</a></p></div><p>Trước đây, làm phần mềm có rào cản rất cao: bạn phải biết lập trình, biết thuật toán, và phải có kinh nghiệm dự án nhiều năm. Bây giờ thì khác. Chỉ cần bạn có ý tưởng, AI có thể giúp bạn viết code.</p><p>Đây là một sự thay đổi lớn: <strong>Ngôn ngữ lập trình đang trở thành ngôn ngữ tự nhiên</strong>.</p><p>Sự xuất hiện của mô hình ngôn ngữ lớn (LLM) khiến phát triển không còn là &quot;đặc quyền của chuyên gia kỹ thuật&quot;, mà trở thành công cụ mà ai cũng có thể sử dụng. Điều khó nhất trước đây là &quot;cách viết code&quot;, bây giờ điều khó nhất là &quot;<strong>Bạn muốn làm gì</strong>&quot;.</p><blockquote><p><strong>Vibe Coding là gì?</strong> Nói đơn giản, đó là &quot;lập trình bằng cách nói chuyện&quot;. Vibe coding có nghĩa là bạn có thể dựa vào việc chỉ đối thoại với AI, thay vì viết code trực tiếp, để hoàn thành dự án lập trình.</p></blockquote><p>Tất nhiên, để AI viết ra code chỉ là bước đầu tiên. Để tạo ra một sản phẩm thực sự sử dụng được, bạn sẽ gặp những vấn đề này:</p><ul><li>Làm sao để AI viết code sạch, có thể bảo trì?</li><li>Làm sao để ghép các đoạn code rời rạc thành một ứng dụng chạy được?</li><li>Làm sao để ứng dụng thực sự trực tuyến, được người khác sử dụng?</li><li>Làm sao để đưa các năng lực AI như tạo văn bản, nhận dạng hình ảnh vào sản phẩm của bạn?</li></ul><p>Những câu hỏi này sẽ tìm thấy câu trả lời trong khóa học này.</p><p>Dù bạn là học sinh, giáo viên, bác sĩ, công nhân, hay bất kỳ ai không biết gì về kỹ thuật -- không cần học lập trình vài năm, chỉ hai tuần đã có thể tạo ra nguyên mẫu sản phẩm chạy được, demo được.</p><table tabindex="0"><thead><tr><th>Vai trò của bạn</th><th>Khóa học này giúp bạn</th></tr></thead><tbody><tr><td>Học sinh</td><td>Bài tập, thi đấu, khởi nghiệp, tự tay làm dự án, không cần cầu cứu ai</td></tr><tr><td>Người đi làm</td><td>Tự động hóa công việc lặp đi lặp lại, nâng cao hiệu suất, thậm chí phát triển nghề tay trái</td></tr><tr><td>Quản lý sản phẩm / Nhà thiết kế</td><td>Ý tưởng không còn dừng lại trên giấy, có thể nhanh chóng tạo Demo cho sếp/khách hàng xem</td></tr><tr><td>Doanh nhân / Chủ doanh nghiệp nhỏ</td><td>Xác minh ý tưởng với chi phí thấp, không cần chi hàng vạn tệ thuê outsource mà vẫn tạo được MVP</td></tr><tr><td>Giáo viên / Nhà giáo dục</td><td>Tạo công cụ giảng dạy, bài giảng, tự động hóa việc ra đề, nâng cao hiệu quả giảng dạy</td></tr><tr><td>Bác sĩ / Luật sư / Chuyên gia</td><td>Tự động hóa quy trình chuyên môn, tạo công cụ hiệu suất của riêng mình</td></tr><tr><td>Bất kỳ ai</td><td>Dùng AI giải quyết các vấn đề cụ thể trong cuộc sống/công việc, biến điều không thể thành có thể</td></tr></tbody></table><p>Trong kỷ nguyên AI, năng lực thực thi và ý tưởng luôn quan trọng hơn kỹ thuật.</p><h2 id="lo-trinh-phat-trien-tu-biet-dung-ai-đen-biet-lam-san-pham-ai" tabindex="-1">Lộ trình phát triển: Từ &quot;biết dùng AI&quot; đến &quot;biết làm sản phẩm AI&quot; <a class="header-anchor" href="#lo-trinh-phat-trien-tu-biet-dung-ai-đen-biet-lam-san-pham-ai" aria-label="Permalink to “Lộ trình phát triển: Từ &quot;biết dùng AI&quot; đến &quot;biết làm sản phẩm AI&quot;”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>Người mới bắt đầu</h3><p class="stage-role">Trải nghiệm lập trình AI</p><div class="stage-tags"><span>Trò chơi rắn săn mồi nhỏ</span><span>Bắt đầu từ con số 0</span><span>Trải nghiệm Vibecoding lần đầu</span><span>Tạo trong vài phút</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>Giai đoạn một</h3><p class="stage-role">Quản lý sản phẩm / Vận hành</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>Phân tách nhu cầu &amp; Nguyên mẫu</span><span>Tích hợp năng lực AI</span><span>Phát triển Demo hoàn chỉnh</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>Giai đoạn hai</h3><p class="stage-role">Phát triển trung cấp / Nhà phát triển độc lập</p><div class="stage-tags"><span>Từ Figma đến code</span><span>Cơ sở dữ liệu Supabase</span><span>Tích hợp thanh toán Stripe</span><span>Cơ sở tri thức Dify</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>Giai đoạn ba</h3><p class="stage-role">Phát triển cấp cao / Kiến trúc sư</p><div class="stage-tags"><span>Web/Mini program/Đa nền tảng</span><span>Công cụ MCP nâng cao</span><span>RAG &amp; LangGraph</span><span>Tư duy kỹ sư cao cấp</span></div></div></div><p>Thông qua lộ trình học tập hoàn chỉnh này, bạn sẽ đạt được:</p><ul><li><strong>Năng lực phát triển Vibe Coding:</strong> Sử dụng thành thạo tư duy vibecoding và công cụ lập trình AI, nâng cao hiệu suất phát triển gấp nhiều lần. Không cần học thuộc cú pháp, mà học cách dẫn dắt AI tạo code chất lượng cao.</li><li><strong>Kỹ năng phát triển full-stack:</strong> Từ thiết kế UI đến thực hiện front-end, từ thiết kế cơ sở dữ liệu đến phát triển API, từ phát triển cục bộ đến triển khai đám mây, làm chủ ngăn xếp công nghệ hoàn chỉnh của ứng dụng Web hiện đại.</li><li><strong>Tích hợp năng lực AI:</strong> Học cách gọi các loại API AI đa phương thức, tích hợp mượt mà các năng lực AI như văn bản, hình ảnh, giọng nói vào ứng dụng của bạn, và xây dựng sản phẩm thông minh thông qua các công nghệ như RAG.</li><li><strong>Tư duy sản phẩm và năng lực vận hành:</strong> Từ nghiên cứu người dùng đến phân tách nhu cầu, từ thiết kế MVP đến lặp lại sản phẩm, từ tích hợp thanh toán đến quản lý người dùng, hình thành vòng lặp hoàn chỉnh phát triển và vận hành sản phẩm.</li></ul><h1 id="hoc-xong-co-the-lam-gi" tabindex="-1">Học xong có thể làm gì? <a class="header-anchor" href="#hoc-xong-co-the-lam-gi" aria-label="Permalink to “Học xong có thể làm gì?”">​</a></h1><h2 id="giai-đoan-mot-tao-nguyen-mau-san-pham-đau-tien-cua-ban" tabindex="-1">Giai đoạn một: Tạo nguyên mẫu sản phẩm đầu tiên của bạn <a class="header-anchor" href="#giai-đoan-mot-tao-nguyen-mau-san-pham-đau-tien-cua-ban" aria-label="Permalink to “Giai đoạn một: Tạo nguyên mẫu sản phẩm đầu tiên của bạn”">​</a></h2><p>Giai đoạn này phù hợp với những bạn hoàn toàn không có nền tảng lập trình, hoặc chỉ biết một chút nhưng không tự tin lắm. Bạn không cần học trước một đống lý thuyết, mà trực tiếp làm theo, trong quá trình làm học cách dùng công cụ AI để viết code.</p><p><strong>Sau khi học xong bạn có thể</strong>:</p><ul><li>Dùng công cụ lập trình AI độc lập hoàn thành một ứng dụng web</li><li>Biến ý tưởng sản phẩm thành nguyên mẫu có thể click, có thể tương tác</li><li>Thêm chức năng AI cho nguyên mẫu (như tạo ảnh từ văn bản, trò chuyện thông minh)</li><li>Khi gặp lỗi biết cách khắc phục và giải quyết</li></ul><p>Nói đơn giản, là có thể tạo ra một thứ &quot;chạy được, demo cho người khác xem được&quot;.</p><p>Chúng ta có thể trước tiên trải nghiệm lập trình AI thông qua trò chơi nhỏ, sau đó học cách dùng công cụ lập trình AI giúp bạn viết code, sửa lỗi. Tiếp theo bắt đầu từ trang đơn giản, từng bước tạo ứng dụng đa trang có thể tương tác, rồi thêm các chức năng AI như tạo ảnh từ văn bản, trò chuyện thông minh. Cuối cùng độc lập hoàn thành một dự án hoàn chỉnh, để ý tưởng sáng tạo của bạn thực sự có khả năng thực hiện.</p><h1 id="tai-sao-phai-dung-phuong-phap-du-an-đe-đao-tao" tabindex="-1">Tại sao phải dùng phương pháp dự án để đào tạo? <a class="header-anchor" href="#tai-sao-phai-dung-phuong-phap-du-an-đe-đao-tao" aria-label="Permalink to “Tại sao phải dùng phương pháp dự án để đào tạo?”">​</a></h1><blockquote><p><strong>Thử thách trong thế giới thực</strong></p><p>Lý do thực ra rất đơn giản: theo tình trạng hiện tại của đa số các bạn, nếu trực tiếp bước vào nơi làm việc, rất có thể sẽ gặp khó khăn dưới sự &quot;đòn roi xã hội&quot; từ dự án thực tế và sếp / khách hàng. Kịch bản phổ biến hơn trong thế giới thực là:</p></blockquote><blockquote><p>Cố vấn / Sếp của bạn: Chúng ta cần làm một xxx, mục tiêu là đạt được hiệu quả yyy.</p><p>Tài liệu? Framework sẵn có? Mô tả nhu cầu chi tiết? Rất nhiều khi không tồn tại.</p></blockquote><p>Nhiều nhiệm vụ trong công việc thực tế, bản chất là giải quyết những vấn đề chưa từng gặp trong môi trường có độ không chắc chắn cao: nhu cầu mơ hồ, ranh giới thay đổi, không ai cho bạn đáp án chuẩn, bạn cần tự tra cứu tài liệu, làm thử nghiệm, xây nguyên mẫu, liên tục lặp lại, cuối cùng đưa ra giải pháp &quot;chạy được, dùng được, có thể trực tuyến&quot;.</p><p>Khóa học này muốn làm chính là trong một môi trường tương đối an toàn, trước mắt cho bạn một &quot;mô phỏng đòn roi xã hội&quot;:</p><ul><li>Thông qua các nhiệm vụ dự án có vẻ hơi khó, buộc bạn luyện tập phân tách vấn đề, thiết kế phương án, tự tìm tài liệu</li><li>Thông qua scaffold và code không quá &quot;dễ dãi&quot;, giúp bạn học cách đọc, hiểu và cải tạo một code base cỡ lớn-trung bình</li><li>Thông qua vòng lặp hoàn chỉnh từ ý tưởng đến trực tuyến, giúp bạn trải nghiệm toàn bộ quá trình từ 0 đến 1 của sản phẩm thực tế</li></ul><p>Ngắn hạn mà nói, loại đào tạo này quả thực khá tra tấn; nhưng về dài hạn, nó sẽ cực kỳ nâng cao năng lực cạnh tranh của bạn trong tìm việc và phát triển nghề nghiệp: bạn sẽ chịu đựng áp lực tốt hơn, dễ tìm ra đột phá trong môi trường không chắc chắn hơn, và có năng lực biến AI thành sản phẩm thực sự triển khai, thay vì dừng lại ở mức &quot;chơi Demo&quot;.</p><h1 id="nghe-thuat-đat-cau-hoi-ky-nang-tat-yeu-trong-ky-nguyen-ai" tabindex="-1">Nghệ thuật đặt câu hỏi: Kỹ năng tất yếu trong kỷ nguyên AI <a class="header-anchor" href="#nghe-thuat-đat-cau-hoi-ky-nang-tat-yeu-trong-ky-nguyen-ai" aria-label="Permalink to “Nghệ thuật đặt câu hỏi: Kỹ năng tất yếu trong kỷ nguyên AI”">​</a></h1><p>Trong kỷ nguyên AI, đặt câu hỏi cũng là một &quot;năng lực cơ bản&quot;. Cùng một đoạn code, cùng một lỗi, <strong>cách bạn đặt câu hỏi, gần như quyết định loại câu trả lời AI có thể đưa ra</strong>: là nói chung chung, hay từng bước đưa ra cách sửa khả thi.</p><p><strong>Hãy tạo thói quen tốt</strong>: Coi &quot;hỏi AI&quot; là một phần của quy trình phát triển hàng ngày: khi gặp vấn đề không hiểu, bị kẹt thì lập tức hỏi.</p><h2 id="tai-sao-đay-la-ky-nang-tat-yeu" tabindex="-1">Tại sao đây là kỹ năng tất yếu? <a class="header-anchor" href="#tai-sao-đay-la-ky-nang-tat-yeu" aria-label="Permalink to “Tại sao đây là kỹ năng tất yếu?”">​</a></h2><ul><li><strong>Thực tế hiếm khi có tài liệu hoàn chỉnh</strong>: Phần nhiều lúc bạn đối mặt với nhu cầu không rõ ràng, code bán thành phẩm, thông tin lỗi rời rạc</li><li><strong>AI là cố vấn + đồng nghiệp bên cạnh bạn</strong>: Người biết đặt câu hỏi, có thể biến nó thành &quot;lập trình cặp chất lượng cao&quot;</li><li><strong>Giới hạn năng lực do giao tiếp quyết định</strong>: Bạn càng cung cấp thông tin quan trọng, càng ràng buộc định dạng đầu ra, câu trả lời càng sử dụng được</li></ul><p><strong>Hiểu lầm phổ biến</strong>: Chỉ hỏi một câu &quot;tại sao báo lỗi?&quot; thường chỉ nhận được một loạt phỏng đoán. Bổ sung đầy đủ ngữ cảnh, mới nhận được phương án khả thi.</p><h2 id="cach-đua-thong-tin-cho-ai-chup-man-hinh-hay-sao-chep-dan" tabindex="-1">Cách đưa thông tin cho AI: Chụp màn hình hay sao chép dán <a class="header-anchor" href="#cach-đua-thong-tin-cho-ai-chup-man-hinh-hay-sao-chep-dan" aria-label="Permalink to “Cách đưa thông tin cho AI: Chụp màn hình hay sao chép dán”">​</a></h2><p>Cả hai cách đều được, nhưng mục đích khác nhau:</p><table tabindex="0"><thead><tr><th>Cách</th><th>Kịch bản phù hợp</th><th>Yêu cầu chính</th></tr></thead><tbody><tr><td><strong>Sao chép dán</strong></td><td>Stack lỗi, log, code, cấu hình, API trả về</td><td>Càng đầy đủ càng tốt, đừng chỉ cắt một dòng từ khóa</td></tr><tr><td><strong>Chụp màn hình</strong></td><td>Vấn đề bố cục UI, tương tác bất thường, không tìm thấy nút trên giao diện công cụ</td><td>Chụp toàn màn hình + đánh dấu vùng trọng điểm, tốt nhất kèm một câu giải thích bằng chữ</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ Điều kiện tiên quyết quan trọng</p><p><strong>Không phải AI nào cũng hỗ trợ đầu vào hình ảnh.</strong> Giao tiếp bằng chụp màn hình cần AI có năng lực đa phương thức (tức là có thể hiểu và phân tích hình ảnh). Hiện tại các AI hỗ trợ đầu vào hình ảnh bao gồm: Claude (Anthropic), GPT-4V/GPT-4o (OpenAI), Gemini (Google), và một số mô hình lớn trong nước như Tongyi Qianwen, Wenxin Yiyan, v.v.</p><p><strong>Nếu AI bạn sử dụng không hỗ trợ đầu vào hình ảnh</strong>, chụp màn hình sẽ không được nhận dạng, lúc này xin hãy dùng cách sao chép dán văn bản để giao tiếp.</p></div><h2 id="meo-prompt-khien-ai-giai-thich-rat-tot" tabindex="-1">Mẹo prompt khiến AI &quot;giải thích rất tốt&quot; <a class="header-anchor" href="#meo-prompt-khien-ai-giai-thich-rat-tot" aria-label="Permalink to “Mẹo prompt khiến AI &quot;giải thích rất tốt&quot;”">​</a></h2><p>Nếu bạn không chỉ muốn câu trả lời, mà muốn &quot;học được&quot; câu trả lời. Sử dụng chỉ dẫn tương tự như dưới đây có thể nâng cao chất lượng giải thích đáng kể:</p><blockquote><p><strong>Ví dụ câu hỏi kiểu học tập</strong></p><ul><li>&quot;Xin hãy dùng 5 câu nói rõ khái niệm này, sau đó đưa vài câu hỏi kiểm tra tôi đã hiểu đúng chưa.&quot;</li><li>&quot;Xin hãy giải thích chi tiết thông tin lỗi này, tôi không hiểu tại sao lại báo lỗi.&quot;</li></ul></blockquote><h1 id="kien-tri-lau-roi-van-khong-xong-toi-muon-bo-cuoc" tabindex="-1">Kiên trì lâu rồi vẫn không xong, tôi muốn bỏ cuộc <a class="header-anchor" href="#kien-tri-lau-roi-van-khong-xong-toi-muon-bo-cuoc" aria-label="Permalink to “Kiên trì lâu rồi vẫn không xong, tôi muốn bỏ cuộc”">​</a></h1><p>Có thể là phương pháp kiên trì của bạn không đúng. Đừng một mình cố gắng trong bóng tối, có thể đến trò chuyện với tác giả và trợ giảng: thành thật nói ra những phương pháp bạn đã thử, điểm kẹt cụ thể bạn gặp phải, và trạng thái tâm lý hiện tại của bạn. Rất nhiều lúc, chỉ cần hơi điều chỉnh hướng đi, bổ sung một kiến thức trọng điểm, bạn lại có thể tiếp tục tiến lên phía trước.</p><h1 id="toi-thay-thiet-ke-cua-giao-trinh-co-cho-khong-hop-ly" tabindex="-1">Tôi thấy thiết kế của giáo trình có chỗ không hợp lý <a class="header-anchor" href="#toi-thay-thiet-ke-cua-giao-trinh-co-cho-khong-hop-ly" aria-label="Permalink to “Tôi thấy thiết kế của giáo trình có chỗ không hợp lý”">​</a></h1><p>Hoan nghênh bất cứ lúc nào liên hệ tác giả, nộp issue, hoặc phản hồi trực tiếp trong nhóm / lớp học. Chúng tôi rất mong cùng bạn mài giũa bộ giáo trình này ngày càng tốt hơn: chỗ nào không rõ ràng, chỗ nào trải nghiệm không tốt, chỗ nào khiến bạn lãng phí công sức, đều có thể thẳng thắn chỉ ra. Phản hồi càng chân thực, càng cụ thể, càng giúp những người sau ít vấp ngáp hơn.</p><h1 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu tham khảo”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">Khoa Khoa học Máy tính và Công nghệ, Đại học Nam Kinh - Thí nghiệm cơ sở hệ thống máy tính</a></li></ul>',50)),r(h,{title:"Tiếp theo có thể học gì",description:"Theo lộ trình 'từ biết dùng AI đến biết làm sản phẩm', tiếp tục tiến lên phía trước.",items:l(t)},null,8,["items"])])}}});export{m as __pageData,b as default};
